import sys
import heapq

def main():
    import sys
    import heapq

    def dijkstra(grid, n, m, w):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        dist = [[float('inf')] * m for _ in range(n)]
        dist[0][0] = 0
        pq = [(0, 0, 0)]  # (distance, x, y)
        portals = {}
        portal_costs = []

        while pq:
            d, x, y = heapq.heappop(pq)
            if d > dist[x][y]:
                continue

            if grid[x][y] > 0:
                if grid[x][y] not in portals:
                    portals[grid[x][y]] = (x, y)
                    portal_costs.append(grid[x][y])
                else:
                    px, py = portals[grid[x][y]]
                    for cost in portal_costs:
                        if cost != grid[x][y]:
                            nx, ny = portals[cost]
                            new_dist = d + cost + grid[x][y]
                            if new_dist < dist[nx][ny]:
                                dist[nx][ny] = new_dist
                                heapq.heappush(pq, (new_dist, nx, ny))

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != -1:
                    new_dist = d + (w if grid[nx][ny] == 0 else grid[nx][ny])
                    if new_dist < dist[nx][ny]:
                        dist[nx][ny] = new_dist
                        heapq.heappush(pq, (new_dist, nx, ny))

        return dist[n-1][m-1] if dist[n-1][m-1] != float('inf') else -1

    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index+1])
    w = int(input[index+2])
    index += 3
    grid = []
    for i in range(n):
        row = list(map(int, input[index:index+m]))
        grid.append(row)
        index += m

    result = dijkstra(grid, n, m, w)
    print(result)

if __name__ == "__main__":
    main()
